import json
from collections import defaultdict

def compute_itinerary():
    # Input variables (constraints)
    total_days = 9
    cities = ["Vienna", "Stockholm", "Nice", "Split"]
    required_days = {
        "Vienna": 2,
        "Stockholm": 5,
        "Nice": 2,
        "Split": 3,
    }
    # Direct flight connections (undirected)
    direct_flights = {
        "Vienna": {"Stockholm", "Nice", "Split"},
        "Stockholm": {"Vienna", "Nice", "Split"},
        "Nice": {"Vienna", "Stockholm"},
        "Split": {"Vienna", "Stockholm"},
    }
    # Day-specific presence constraints
    # Interpretation: on these days, the city must be included (either by staying there or by flying into/from it)
    presence_constraints = {
        1: {"Vienna"},
        2: {"Vienna"},
        7: {"Split"},
        9: {"Split"},
    }
    # Starting city assumption (consistent with being in Vienna on Day 1)
    start_city = "Vienna"

    # Precompute some values
    city_index = {c: i for i, c in enumerate(cities)}
    req_tuple_target = tuple(required_days[c] for c in cities)

    # State: (day, current_city, counts_tuple)
    # We store the minimal number of flights used to reach this state; if we revisit with >=, we prune
    visited_min_flights = {}

    best_solution = {"flights": float("inf"), "plan": None}

    def can_satisfy_remaining(counts, day, cur_city):
        remaining_days = total_days - day
        # Quick feasibility checks:
        # 1) No city should exceed required days
        for c in cities:
            if counts[c] > required_days[c]:
                return False
        # 2) Each city's remaining need must be <= maximum possible remaining contributions (remaining_days)
        # This is a loose upper bound but effective for pruning
        for c in cities:
            need = required_days[c] - counts[c]
            if need > remaining_days:
                return False
        return True

    def includes_required_city_today(day, included_set):
        must = presence_constraints.get(day, set())
        return must.issubset(included_set)

    def dfs(day, current_city, counts, plan, flights_count):
        # Prune by current best
        state_key = (day, current_city, tuple(counts[c] for c in cities))
        prev_best = visited_min_flights.get(state_key)
        if prev_best is not None and flights_count >= prev_best:
            return
        visited_min_flights[state_key] = flights_count

        if not can_satisfy_remaining(counts, day - 1, current_city):
            return

        if day > total_days:
            # Check if counts match exactly
            if all(counts[c] == required_days[c] for c in cities):
                # Found feasible solution; update best if fewer flights
                if flights_count < best_solution["flights"]:
                    best_solution["flights"] = flights_count
                    best_solution["plan"] = list(plan)
            return

        # Enumerate actions for the day
        # Priority: stay first (to minimize flights), then flights to neighbors (sorted for determinism)
        actions = []

        # Stay action
        actions.append(("stay", current_city))

        # Fly actions (at most one flight per day)
        for nxt in sorted(direct_flights[current_city]):
            actions.append(("fly", nxt))

        for action, target in actions:
            if action == "stay":
                included = {current_city}
                if not includes_required_city_today(day, included):
                    continue
                # Update counts
                new_counts = counts.copy()
                new_counts[current_city] += 1
                # Prune if exceeds
                if new_counts[current_city] > required_days[current_city]:
                    continue
                if not can_satisfy_remaining(new_counts, day, current_city):
                    continue
                plan.append(("stay", current_city, current_city))  # (action, origin, destination)
                dfs(day + 1, current_city, new_counts, plan, flights_count)
                plan.pop()
            else:
                # Flight to target
                nxt = target
                # Ensure direct flight exists (redundant due to enumeration)
                if nxt not in direct_flights[current_city]:
                    continue
                included = {current_city, nxt}
                if not includes_required_city_today(day, included):
                    continue
                new_counts = counts.copy()
                new_counts[current_city] += 1
                new_counts[nxt] += 1
                # Prune if exceeds on either city
                if new_counts[current_city] > required_days[current_city] or new_counts[nxt] > required_days[nxt]:
                    continue
                if not can_satisfy_remaining(new_counts, day, nxt):
                    continue
                plan.append(("fly", current_city, nxt))
                dfs(day + 1, nxt, new_counts, plan, flights_count + 1)
                plan.pop()

    # Initialize counts and plan
    initial_counts = {c: 0 for c in cities}
    dfs(1, start_city, initial_counts, [], 0)

    if best_solution["plan"] is None:
        raise RuntimeError("No feasible itinerary found under given constraints.")

    # Build human-friendly per-day summary
    day_entries = []
    cur_city = start_city
    for day_idx, (action, origin, dest) in enumerate(best_solution["plan"], start=1):
        if action == "stay":
            label = origin
        else:
            label = f"{origin} -> {dest} (flight)"
            cur_city = dest
        day_entries.append((day_idx, label))

    # Aggregate contiguous same-label days into ranges
    itinerary = []
    if day_entries:
        start = day_entries[0][0]
        prev_label = day_entries[0][1]
        for i in range(1, len(day_entries)):
            d, label = day_entries[i]
            if label == prev_label:
                continue
            else:
                if start == day_entries[i-1][0]:
                    day_range = f"Day {start}"
                else:
                    day_range = f"Day {start}-{day_entries[i-1][0]}"
                itinerary.append({"day_range": day_range, "place": prev_label})
                start = d
                prev_label = label
        # Add last segment
        last_day = day_entries[-1][0]
        if start == last_day:
            day_range = f"Day {start}"
        else:
            day_range = f"Day {start}-{last_day}"
        itinerary.append({"day_range": day_range, "place": prev_label})

    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result, ensure_ascii=False))
